async function generate(existingPayload, sessionData) {
  applyContextDefaults(existingPayload, sessionData);

  if (existingPayload.message?.order) {
    const order = buildOrderFromUserInputs(sessionData?.user_inputs);
    existingPayload.message.order.provider = order.provider;
    existingPayload.message.order.items = order.items;
    existingPayload.message.order.fulfillments = order.fulfillments;
  }

  return existingPayload;
}

/**
 * Refreshes context.timestamp/message_id, and echoes the ongoing
 * transaction_id/bap_uri/bpp_uri from session if present.
 */
function applyContextDefaults(existingPayload, sessionData) {
  if (!existingPayload.context) return;

  existingPayload.context.timestamp = new Date().toISOString();
  existingPayload.context.message_id = uuidv4();

  if (sessionData?.transaction_id) {
    existingPayload.context.transaction_id = sessionData.transaction_id;
  }
  if (sessionData?.bapUri) {
    existingPayload.context.bap_uri = sessionData.bapUri;
  }
  if (sessionData?.bppUri) {
    existingPayload.context.bpp_uri = sessionData.bppUri;
  }
}

/**
 * Builds provider/items/fulfillments from the flat user_inputs fields
 * (providerId, itemId, itemValue, fulfillmentId, creds, personId,
 * customerPersonId). Does NOT touch tags or any other order field —
 * caller merges these three keys onto the existing order individually.
 */
function buildOrderFromUserInputs(userInputs) {
  if (!userInputs) {
    return { provider: {}, items: [], fulfillments: [] };
  }

  const {
    providerId,
    itemId,
    itemValue,
    fulfillmentId,
    creds,
    personId,
    customerPersonId
  } = userInputs;

  return {
    provider: { id: providerId },
    items: [
      {
        id: itemId,
        quantity: {
          selected: {
            measure: { value: itemValue, unit: "INR" }
          }
        },
        fulfillment_ids: [fulfillmentId]
      }
    ],
    fulfillments: [
      {
        id: fulfillmentId,
        type: "LUMPSUM",
        customer: {
          person: { id: customerPersonId }
        },
        agent: {
          person: { id: personId },
          organization: { creds: creds ?? [] }
        }
      }
    ]
  };
}

function validate(payload,sessionData) {
