async function generate(existingPayload, sessionData) {

  const order = existingPayload?.message?.order;

  if (!order) {
    console.error("Order object not found in existingPayload");
    return existingPayload;
  }

  // --------------------------------------------------
  // Parse user inputs
  // --------------------------------------------------

  const userInput =sessionData?.user_inputs;
  if (userInput.providerId) {
    order.provider = {
      ...order.provider,
      id: userInput.providerId
    };
  }

  // --------------------------------------------------
  // Update Item
  // --------------------------------------------------

  if (userInput.itemId && order.items?.length) {
    const item = order.items[0];

    item.id = userInput.itemId;

    if (userInput.itemValue !== undefined) {
      item.quantity = {
        ...item.quantity,
        selected: {
          ...item.quantity?.selected,
          measure: {
            ...item.quantity?.selected?.measure,
            value: String(userInput.itemValue),
            unit:
              item.quantity?.selected?.measure?.unit || "INR"
          }
        }
      };
    }

    // Update fulfillment reference on item
    if (userInput.fulfillmentId) {
      item.fulfillment_ids = [userInput.fulfillmentId];
    }
  }

  // --------------------------------------------------
  // Update Fulfillment
  // --------------------------------------------------

  if (order.fulfillments?.length) {
    const fulfillment = order.fulfillments[0];

    if (userInput.fulfillmentId) {
      fulfillment.id = userInput.fulfillmentId;
    }

    // Agent Person
    if (userInput.personId) {
      fulfillment.agent = {
        ...fulfillment.agent,
        person: {
          ...fulfillment.agent?.person,
          id: userInput.personId
        }
      };
    }

    // Agent Organization Credentials
    if (Array.isArray(userInput.creds)) {
      fulfillment.agent = {
        ...fulfillment.agent,
        organization: {
          ...fulfillment.agent?.organization,
          creds: userInput.creds
        }
      };
    }

    // Customer Person
    if (userInput.customerPersonId) {
      fulfillment.customer = {
        ...fulfillment.customer,
        person: {
          ...fulfillment.customer?.person,
          id: userInput.customerPersonId
        }
      };
    }
  }


  return existingPayload;
}

