  const DEFAULT_USER_INPUT = {
    message: {
      order: {
        provider: { id: "", descriptor: { name: "" } },
        items: [],
        fulfillments: [],
      },
    },
  };

  const rawData = sessionData?.user_inputs?.data;

  let userInput;

  if (typeof rawData === "string") {
    try {
      userInput = JSON.parse(rawData);
    } catch (err) {
      console.error("Invalid JSON string in user_inputs.data:", err);
      userInput = DEFAULT_USER_INPUT;
    }
  } else if (rawData && typeof rawData === "object") {
    userInput = rawData;
  } else {
    console.warn("user_inputs.data is missing or invalid. Using defaults.");
    userInput = DEFAULT_USER_INPUT;
  }

  // Safely resolve order fields with fallback to defaults
  const order = userInput?.message?.order ?? DEFAULT_USER_INPUT.message.order;

  // Collect all fulfillment IDs to attach to each item
  const fulfillment_ids = (order.fulfillments ?? [])
    .map((fulfillment) => fulfillment?.id)
    .filter(Boolean); // Remove undefined/null IDs

  // Populate provider — fallback to empty structured default
  existingPayload.message.order.provider = order.provider ?? DEFAULT_USER_INPUT.message.order.provider;

  // Populate items — attach fulfillment_ids to each, preserve all other item fields
  existingPayload.message.order.items = (order.items ?? []).map((item) => ({
    ...item,
    fulfillment_ids,
  }));

