async function generate(existingPayload, sessionData) {

  const rawData = sessionData?.user_inputs?.data

  let userInput

  if (typeof rawData === "string") {
    try {
      userInput = JSON.parse(rawData)
    } catch (err) {
      userInput = {}
    }
  } else {
    userInput = rawData
  }
  const fulfillment_ids =
    userInput?.message?.order?.fulfillments?.map(fulfillment => {
      return fulfillment?.id
    }) ?? []
  existingPayload.message.order.provider =
    userInput?.message?.order?.provider ?? {}
  existingPayload.message.order.items =
    userInput?.message?.order?.items?.map(item => {
      return {
        ...item,
        fulfillment_ids
      }
    }) ?? []
  existingPayload.message.order.fulfillments =
    userInput?.message?.order?.fulfillments ?? []

  return existingPayload
}

